// Validate và chuẩn hóa input từ webhook
const body = $input.first().json.body || $input.first().json;

// Kiểm tra transcript bắt buộc
if (!body.transcript || String(body.transcript).trim().length < 50) {
  throw new Error('❌ Transcript không hợp lệ hoặc quá ngắn (tối thiểu 50 ký tự)');
}

// Chuẩn hóa ai_model
const ai_model = (body.ai_model || 'gemini').toLowerCase();
if (!['gemini', 'deepseek'].includes(ai_model)) {
  throw new Error('❌ ai_model phải là "gemini" hoặc "deepseek"');
}

// Xử lý danh sách attendees
const attendees = Array.isArray(body.attendees)
  ? body.attendees.filter(Boolean)
  : (body.attendees ? String(body.attendees).split(',').map(e => e.trim()).filter(Boolean) : []);

const attendeeNames = Array.isArray(body.attendee_names)
  ? body.attendee_names.filter(Boolean)
  : (body.attendee_names ? String(body.attendee_names).split(',').map(n => n.trim()).filter(Boolean) : attendees);

// Format ngày họp
const meetingDate = body.meeting_date || new Date().toISOString().split('T')[0];

// Tạo Request ID duy nhất
const requestId = `MTG-${Date.now()}`;

return [{
  json: {
    meeting_title: body.meeting_title || 'Cuộc Họp Không Tên',
    meeting_date: meetingDate,
    attendees: attendees,
    attendee_names: attendeeNames,
    attendees_count: attendees.length,
    transcript: String(body.transcript).trim(),
    transcript_length: String(body.transcript).trim().length,
    ai_model: ai_model,
    organizer_email: body.organizer_email || '',
    notification_chat_id: String(body.notification_chat_id || ''),
    sheet_id: body.sheet_id || 'NHẬP_GOOGLE_SHEET_ID',
    request_id: requestId,
    received_at: new Date().toISOString()
  }
}];

const data = $input.first().json;

// Format ngày họp theo tiếng Việt
const dateObj = new Date(data.meeting_date + 'T00:00:00+07:00');
const formattedDate = dateObj.toLocaleDateString('vi-VN', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  timeZone: 'Asia/Ho_Chi_Minh'
});

const attendeeList = data.attendee_names.length > 0
  ? data.attendee_names.join(', ')
  : 'Không xác định';

// Xây dựng prompt phân tích transcript
const prompt = `Bạn là chuyên gia phân tích và tổng hợp biên bản cuộc họp (Meeting Minutes) chuyên nghiệp.

Hãy phân tích transcript cuộc họp dưới đây và tạo biên bản cuộc họp đầy đủ, chuẩn xác.

## THÔNG TIN CUỘC HỌP:
- Tên cuộc họp: ${data.meeting_title}
- Ngày tổ chức: ${formattedDate}
- Người tham dự (${data.attendees_count} người): ${attendeeList}

## NỘI DUNG TRANSCRIPT:
${data.transcript}

## YÊU CẦU OUTPUT:
Trả về JSON hợp lệ với cấu trúc sau (KHÔNG có markdown wrapper):
{
  "meeting_summary": "Tóm tắt tổng quan cuộc họp trong 2-3 câu súc tích",
  "key_topics": [
    {
      "topic": "Tên chủ đề thảo luận",
      "summary": "Tóm tắt nội dung thảo luận",
      "outcome": "Kết quả hoặc quyết định đạt được"
    }
  ],
  "key_decisions": [
    {
      "decision": "Quyết định cụ thể được đưa ra",
      "owner": "Người chịu trách nhiệm thực hiện",
      "rationale": "Lý do/bối cảnh dẫn đến quyết định"
    }
  ],
  "action_items": [
    {
      "task": "Mô tả công việc cụ thể cần làm",
      "owner": "Người thực hiện",
      "deadline": "Thời hạn hoàn thành (YYYY-MM-DD hoặc mô tả)",
      "priority": "high|medium|low",
      "notes": "Ghi chú bổ sung nếu có"
    }
  ],
  "next_steps": "Mô tả các bước tiếp theo sau cuộc họp này",
  "next_meeting": {
    "suggested_date": "Ngày đề xuất hoặc mô tả thời gian họp tiếp",
    "agenda_preview": "Dự kiến nội dung agenda lần họp tiếp theo"
  },
  "meeting_effectiveness_score": 8,
  "improvement_suggestions": "Gợi ý để cải thiện chất lượng cuộc họp lần sau"
}

QUAN TRỌNG:
- Chỉ sử dụng thông tin có trong transcript, KHÔNG tự sáng tạo
- Nếu không có thông tin cho trường nào, để giá trị rỗng ""
- Viết tiếng Việt cho toàn bộ nội dung
- Output PHẢI là JSON thuần túy, không có text hay markdown thêm vào`;

return [{
  json: {
    ...data,
    formatted_date: formattedDate,
    prompt: prompt
  }
}];

