parameters.jsCode:
// Parse AI response (hỗ trợ cả Gemini và DeepSeek format)
const aiResponse = $input.first().json;
let meetingMinutes;

try {
  // Format 1: Google Gemini API response
  if (aiResponse.candidates && aiResponse.candidates[0]) {
    const text = aiResponse.candidates[0]?.content?.parts?.[0]?.text;
    if (!text) throw new Error('Gemini response trống');
    meetingMinutes = JSON.parse(text);
  }
  // Format 2: DeepSeek / OpenAI-compatible response
  else if (aiResponse.choices && aiResponse.choices[0]) {
    const text = aiResponse.choices[0]?.message?.content;
    if (!text) throw new Error('DeepSeek response trống');
    // Loại bỏ markdown wrapper nếu có
    const cleanText = text.replace(/^```json\s*/m, '').replace(/```\s*$/m, '').trim();
    meetingMinutes = JSON.parse(cleanText);
  }
  else {
    throw new Error(`Không nhận được response hợp lệ từ AI. Keys: ${Object.keys(aiResponse).join(', ')}`);
  }
} catch(e) {
  const raw = JSON.stringify(aiResponse).substring(0, 300);
  throw new Error(`❌ Lỗi parse AI response: ${e.message}\nRaw (300 chars): ${raw}`);
}

// Lấy lại dữ liệu gốc từ node Tạo AI Prompt
const orig = $('📝 Tạo AI Prompt').first().json;

// Normalize fields với default values
const keyTopics = Array.isArray(meetingMinutes.key_topics) ? meetingMinutes.key_topics : [];
const keyDecisions = Array.isArray(meetingMinutes.key_decisions) ? meetingMinutes.key_decisions : [];
const actionItems = Array.isArray(meetingMinutes.action_items) ? meetingMinutes.action_items : [];
const nextMeeting = meetingMinutes.next_meeting || {};
const score = Number(meetingMinutes.meeting_effectiveness_score) || 0;

// Format action items thành text có emoji
const actionItemsText = actionItems
  .map((item, i) => {
    const p = item.priority === 'high' ? '🔴' : item.priority === 'medium' ? '🟡' : '🟢';
    return `${i + 1}. ${p} ${item.task}\n   👤 ${item.owner} | 📅 ${item.deadline || 'TBD'}`;
  })
  .join('\n\n');

// Format decisions thành text
const decisionsText = keyDecisions
  .map((d, i) => `${i + 1}. ✅ ${d.decision}\n   👤 ${d.owner}`)
  .join('\n\n');

return [{
  json: {
    // Thông tin cuộc họp gốc
    meeting_title: orig.meeting_title,
    meeting_date: orig.meeting_date,
    formatted_date: orig.formatted_date,
    attendees: orig.attendees,
    attendee_names: orig.attendee_names,
    attendees_count: orig.attendees_count,
    organizer_email: orig.organizer_email,
    notification_chat_id: orig.notification_chat_id,
    sheet_id: orig.sheet_id,
    request_id: orig.request_id,
    ai_model: orig.ai_model,
    received_at: orig.received_at,

    // Kết quả phân tích từ AI
    meeting_summary: meetingMinutes.meeting_summary || '',
    key_topics: keyTopics,
    key_decisions: keyDecisions,
    action_items: actionItems,
    next_steps: meetingMinutes.next_steps || '',
    next_meeting: nextMeeting,
    effectiveness_score: score,
    improvement_suggestions: meetingMinutes.improvement_suggestions || '',

    // Formatted text versions
    action_items_text: actionItemsText,
    decisions_text: decisionsText,
    action_items_count: actionItems.length,
    decisions_count: keyDecisions.length,
    topics_count: keyTopics.length,

    processed_at: new Date().toISOString()
  }
}];

const data = $input.first().json;

// ===== EMAIL HTML =====
const priorityBadge = (p) => {
  if (p === 'high') return '<span style="background:#fee2e2;color:#dc2626;padding:2px 8px;border-radius:12px;font-size:12px;font-weight:bold;">🔴 CAO</span>';
  if (p === 'medium') return '<span style="background:#fef9c3;color:#ca8a04;padding:2px 8px;border-radius:12px;font-size:12px;font-weight:bold;">🟡 TB</span>';
  return '<span style="background:#dcfce7;color:#16a34a;padding:2px 8px;border-radius:12px;font-size:12px;font-weight:bold;">🟢 THẤP</span>';
};

const actionRowsHtml = (data.action_items || []).map((item, i) => `
  <tr style="background:${i % 2 === 0 ? '#ffffff' : '#f8fafc'}">
    <td style="padding:10px 12px;border:1px solid #e2e8f0;text-align:center;font-weight:bold;">${i + 1}</td>
    <td style="padding:10px 12px;border:1px solid #e2e8f0;">${item.task}</td>
    <td style="padding:10px 12px;border:1px solid #e2e8f0;">${item.owner}</td>
    <td style="padding:10px 12px;border:1px solid #e2e8f0;">${item.deadline || 'TBD'}</td>
    <td style="padding:10px 12px;border:1px solid #e2e8f0;text-align:center;">${priorityBadge(item.priority)}</td>
  </tr>`).join('');

const topicsHtml = (data.key_topics || []).map((t, i) => `
  <div style="margin-bottom:16px;padding:14px;background:#f8fafc;border-left:4px solid #6366f1;border-radius:0 8px 8px 0;">
    <div style="font-weight:bold;color:#1e293b;margin-bottom:6px;">${i + 1}. ${t.topic}</div>
    <div style="color:#475569;font-size:14px;margin-bottom:6px;">${t.summary}</div>
    <div style="color:#6366f1;font-size:13px;">→ Kết quả: <em>${t.outcome}</em></div>
  </div>`).join('');

const decisionsHtml = (data.key_decisions || []).map((d, i) => `
  <li style="margin-bottom:10px;padding:10px;background:#f0fdf4;border-radius:6px;">
    <strong style="color:#166534;">${d.decision}</strong>
    <div style="color:#4ade80;font-size:13px;margin-top:4px;">👤 ${d.owner}${d.rationale ? ' — ' + d.rationale : ''}</div>
  </li>`).join('');

const aiModelName = data.ai_model === 'gemini' ? 'Google Gemini 2.0 Flash' : 'DeepSeek Chat';

const emailHtml = `<!DOCTYPE html>
<html lang="vi">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="font-family:'Segoe UI',Arial,sans-serif;max-width:720px;margin:0 auto;padding:20px;color:#1e293b;background:#f1f5f9;">

<div style="background:linear-gradient(135deg,#6366f1,#8b5cf6);padding:28px 32px;border-radius:12px 12px 0 0;">
  <h1 style="color:white;margin:0 0 8px;font-size:24px;">📋 Biên Bản Cuộc Họp</h1>
  <p style="color:rgba(255,255,255,0.85);margin:0;font-size:18px;font-weight:500;">${data.meeting_title}</p>
</div>

<div style="background:white;padding:24px 32px;border-radius:0 0 12px 12px;box-shadow:0 4px 6px rgba(0,0,0,0.05);">

  <table style="width:100%;border-collapse:collapse;margin-bottom:28px;border-radius:8px;overflow:hidden;">
    <tr><td style="padding:10px 16px;background:#f1f5f9;font-weight:600;width:35%;">📅 Ngày họp</td><td style="padding:10px 16px;border-bottom:1px solid #f1f5f9;">${data.formatted_date}</td></tr>
    <tr><td style="padding:10px 16px;background:#f1f5f9;font-weight:600;">👥 Người tham dự</td><td style="padding:10px 16px;border-bottom:1px solid #f1f5f9;">${data.attendee_names.join(', ')}</td></tr>
    <tr><td style="padding:10px 16px;background:#f1f5f9;font-weight:600;">🤖 Phân tích bởi</td><td style="padding:10px 16px;border-bottom:1px solid #f1f5f9;">${aiModelName}</td></tr>
    <tr><td style="padding:10px 16px;background:#f1f5f9;font-weight:600;">⭐ Hiệu quả họp</td><td style="padding:10px 16px;">${data.effectiveness_score}/10</td></tr>
  </table>

  <h2 style="color:#6366f1;border-bottom:2px solid #e2e8f0;padding-bottom:10px;font-size:18px;">📌 Tóm Tắt</h2>
  <p style="background:#f0fdf4;padding:14px 16px;border-radius:8px;border-left:4px solid #22c55e;line-height:1.7;">${data.meeting_summary}</p>

  <h2 style="color:#6366f1;border-bottom:2px solid #e2e8f0;padding-bottom:10px;font-size:18px;">💬 Nội Dung Thảo Luận</h2>
  ${topicsHtml}

  <h2 style="color:#6366f1;border-bottom:2px solid #e2e8f0;padding-bottom:10px;font-size:18px;">✅ Quyết Định Đã Đưa Ra (${data.decisions_count})</h2>
  <ul style="list-style:none;padding:0;margin:0 0 24px;">${decisionsHtml}</ul>

  <h2 style="color:#6366f1;border-bottom:2px solid #e2e8f0;padding-bottom:10px;font-size:18px;">📌 Action Items (${data.action_items_count})</h2>
  <table style="width:100%;border-collapse:collapse;margin-bottom:24px;">
    <thead>
      <tr style="background:#6366f1;color:white;">
        <th style="padding:10px 12px;text-align:center;width:40px;">#</th>
        <th style="padding:10px 12px;text-align:left;">Công Việc</th>
        <th style="padding:10px 12px;text-align:left;">Người TH</th>
        <th style="padding:10px 12px;text-align:left;">Deadline</th>
        <th style="padding:10px 12px;text-align:center;">Ưu Tiên</th>
      </tr>
    </thead>
    <tbody>${actionRowsHtml}</tbody>
  </table>

  ${data.next_steps ? `<h2 style="color:#6366f1;border-bottom:2px solid #e2e8f0;padding-bottom:10px;font-size:18px;">🚀 Bước Tiếp Theo</h2><p style="line-height:1.7;margin-bottom:24px;">${data.next_steps}</p>` : ''}

  ${data.next_meeting && data.next_meeting.suggested_date ? `<div style="background:#eff6ff;padding:14px 16px;border-radius:8px;border-left:4px solid #3b82f6;margin-bottom:24px;"><strong>📅 Họp tiếp theo:</strong> ${data.next_meeting.suggested_date}<br><span style="color:#3b82f6;font-size:14px;">${data.next_meeting.agenda_preview || ''}</span></div>` : ''}

  ${data.improvement_suggestions ? `<div style="background:#fffbeb;padding:14px 16px;border-radius:8px;border-left:4px solid #f59e0b;margin-bottom:24px;"><strong>💡 Gợi ý cải thiện:</strong><br>${data.improvement_suggestions}</div>` : ''}

  <hr style="border:1px solid #e2e8f0;margin:24px 0;">
  <p style="color:#94a3b8;font-size:12px;text-align:center;">
    Biên bản tạo tự động bởi n8n + ${aiModelName} | 
    ${new Date().toLocaleString('vi-VN', {timeZone: 'Asia/Ho_Chi_Minh'})} | 
    ID: ${data.request_id}
  </p>

</div>
</body></html>`;

// ===== TELEGRAM MESSAGE =====
const topActionItems = (data.action_items || []).slice(0, 5)
  .map((item, i) => {
    const p = item.priority === 'high' ? '🔴' : item.priority === 'medium' ? '🟡' : '🟢';
    return `  ${i + 1}. ${p} ${item.task}\n     👤 ${item.owner} | ${item.deadline || 'TBD'}`;
  }).join('\n');

const topDecisions = (data.key_decisions || []).slice(0, 3)
  .map((d, i) => `  ${i + 1}. ${d.decision}`)
  .join('\n');

const telegramMessage = `📋 <b>BIÊN BẢN CUỘC HỌP</b>
━━━━━━━━━━━━━━━━━━━━

📌 <b>${data.meeting_title}</b>
📅 ${data.formatted_date}
👥 ${data.attendees_count} người tham dự
🤖 AI: ${data.ai_model === 'gemini' ? 'Gemini 2.0' : 'DeepSeek'} | ⭐ ${data.effectiveness_score}/10

<b>📝 Tóm tắt:</b>
${data.meeting_summary}

<b>✅ Quyết định (${data.decisions_count}):</b>
${topDecisions || '  (Không có quyết định)'}

<b>📌 Action Items (${data.action_items_count}):</b>
${topActionItems || '  (Không có action items)'}
${data.action_items_count > 5 ? `  <i>... và ${data.action_items_count - 5} items khác (xem email)</i>` : ''}

${data.next_meeting && data.next_meeting.suggested_date ? `📅 <b>Họp tiếp:</b> ${data.next_meeting.suggested_date}` : ''}
━━━━━━━━━━━━━━━━━━━━
<i>✉️ Email đã gửi cho ${data.attendees_count} người</i>
<i>📊 Đã lưu Google Sheets | ID: ${data.request_id}</i>`;

// ===== GOOGLE SHEETS DATA =====
const sheetsRow = {
  'Request ID': data.request_id,
  'Meeting Title': data.meeting_title,
  'Meeting Date': data.meeting_date,
  'Attendees': data.attendee_names.join(', '),
  'Attendees Count': data.attendees_count,
  'Summary': data.meeting_summary,
  'Action Items Count': data.action_items_count,
  'Decisions Count': data.decisions_count,
  'Topics Count': data.topics_count,
  'Effectiveness Score': data.effectiveness_score,
  'Next Meeting': (data.next_meeting && data.next_meeting.suggested_date) || '',
  'AI Model': data.ai_model,
  'Email Recipients': data.attendees.join(', '),
  'Processed At': data.processed_at,
  'Action Items JSON': JSON.stringify(data.action_items),
  'Decisions JSON': JSON.stringify(data.key_decisions)
};

return [{
  json: {
    ...data,
    email_html: emailHtml,
    telegram_message: telegramMessage,
    sheets_row: sheetsRow,
    email_to: data.attendees.length > 0 ? data.attendees.join(',') : data.organizer_email,
    has_telegram: data.notification_chat_id && data.notification_chat_id.length > 2
  }
}];

